/// Read the response body into bytes.
async fn body_bytes(response: axum::response::Response) -> Vec<u8> {
    axum::body::to_bytes(response.into_body(), 1024 * 1024)
        .await
        .expect("failed to read response body")
        .to_vec()
}

fn decode_fmvp_payload_f64(bytes: &[u8]) -> Vec<f64> {
    assert!(
        bytes.len() >= 48,
        "FMVP payload must include a 48 byte header"
    );
    let values_offset = fmvp_values_offset(bytes);
    bytes[values_offset..]
        .chunks_exact(8)
        .map(|chunk| {
            f64::from_le_bytes(
                chunk
                    .try_into()
                    .expect("FMVP f64 payload chunks should be 8 bytes"),
            )
        })
        .collect()
}

fn fmvp_values_offset(bytes: &[u8]) -> usize {
    assert!(
        bytes.len() >= 48,
        "FMVP payload must include a 48 byte header"
    );
    if bytes[4] == 3 {
        let metadata_len = u32::from_le_bytes(bytes[8..12].try_into().unwrap()) as usize;
        48 + metadata_len
    } else {
        48
    }
}

fn decode_fmvp_node_indices(bytes: &[u8]) -> Vec<u32> {
    assert_eq!(&bytes[..4], b"FMVP");
    assert_eq!(bytes[4], 3, "node indices require FMVP v3 metadata");
    let metadata_len = u32::from_le_bytes(bytes[8..12].try_into().unwrap()) as usize;
    let metadata_end = 48 + metadata_len;
    assert_eq!(&bytes[48..52], b"FMMI");
    let node_index_count = u32::from_le_bytes(bytes[108..112].try_into().unwrap()) as usize;
    let scope_kind_len = u16::from_le_bytes(bytes[112..114].try_into().unwrap()) as usize;
    let scope_id_len = u16::from_le_bytes(bytes[114..116].try_into().unwrap()) as usize;
    let metadata_version = u16::from_le_bytes(bytes[52..54].try_into().unwrap());
    let generation_len = if metadata_version >= 2 {
        u16::from_le_bytes(bytes[56..58].try_into().unwrap()) as usize
    } else {
        0
    };
    let node_indices_start = 116 + scope_kind_len + scope_id_len + generation_len;
    assert!(node_indices_start + node_index_count * 4 <= metadata_end);
    (0..node_index_count)
        .map(|index| {
            let start = node_indices_start + index * 4;
            u32::from_le_bytes(bytes[start..start + 4].try_into().unwrap())
        })
        .collect()
}

fn decode_fmvp_metadata_scope(bytes: &[u8]) -> (String, String) {
    assert_eq!(&bytes[..4], b"FMVP");
    assert_eq!(bytes[4], 3, "scope provenance requires FMVP v3 metadata");
    assert_eq!(&bytes[48..52], b"FMMI");
    let scope_kind_len = u16::from_le_bytes(bytes[112..114].try_into().unwrap()) as usize;
    let scope_id_len = u16::from_le_bytes(bytes[114..116].try_into().unwrap()) as usize;
    let scope_start = 116;
    let scope_kind_end = scope_start + scope_kind_len;
    let scope_id_end = scope_kind_end + scope_id_len;
    (
        std::str::from_utf8(&bytes[scope_start..scope_kind_end])
            .expect("FMVP metadata scope kind must be UTF-8")
            .to_string(),
        std::str::from_utf8(&bytes[scope_kind_end..scope_id_end])
            .expect("FMVP metadata scope id must be UTF-8")
            .to_string(),
    )
}

fn decode_fmvp_topology_revision(bytes: &[u8]) -> u64 {
    assert_eq!(&bytes[..4], b"FMVP");
    assert_eq!(bytes[4], 3, "topology revision requires FMVP v3 metadata");
    assert_eq!(&bytes[48..52], b"FMMI");
    u64::from_le_bytes(bytes[64..72].try_into().unwrap())
}

/// Read and parse the response body as JSON.
async fn body_json(response: axum::response::Response) -> serde_json::Value {
    let bytes = body_bytes(response).await;
    serde_json::from_slice(&bytes).expect("response body is not valid JSON")
}

fn assert_hysteresis_points_resource<'a>(
    resource: &'a serde_json::Value,
    expected_stage_index: u64,
) -> &'a serde_json::Value {
    assert!(
        resource["revision"].as_u64().is_some(),
        "hysteresis points resource must expose a numeric revision"
    );
    assert_eq!(resource["stage_index"], expected_stage_index);
    resource
        .get("points")
        .expect("hysteresis points resource must expose points")
}

fn is_iso_calendar_date(value: &str) -> bool {
    let bytes = value.as_bytes();
    bytes.len() == 10
        && bytes[4] == b'-'
        && bytes[7] == b'-'
        && bytes
            .iter()
            .enumerate()
            .all(|(index, byte)| matches!(index, 4 | 7) || byte.is_ascii_digit())
}

