#[tokio::test]
async fn domain_topology_supports_byte_ranges_for_large_topology_payloads() {
    let state = test_app_state_with_live_session().await;
    if let Some(snapshot) = state.current_live_state.write().await.as_mut() {
        snapshot.fem_mesh = Some(sample_fem_mesh_payload());
        snapshot.mesh_revision = 18;
    }
    let cache_state = state.clone();
    let app = build_v2_router().with_state(state);

    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/data/domain/topology")
                .header("range", "bytes=0-3")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(response.status(), StatusCode::PARTIAL_CONTENT);
    assert_eq!(
        response
            .headers()
            .get("accept-ranges")
            .and_then(|value| value.to_str().ok()),
        Some("bytes")
    );
    assert_eq!(
        response
            .headers()
            .get("content-range")
            .and_then(|value| value.to_str().ok()),
        Some("bytes 0-3/264")
    );
    let body = body_bytes(response).await;
    assert_eq!(&body[..], b"FMMT");

    let second = app
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/data/domain/topology")
                .header("range", "bytes=64-71")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(second.status(), StatusCode::PARTIAL_CONTENT);
    assert_eq!(
        cache_state
            .quantity_data_plane
            .topology_cache
            .lock()
            .expect("topology cache lock")
            .len(),
        1
    );
}

