#[tokio::test]
async fn mesh_shared_domain_quality_data_returns_binary_artifact() {
    let artifact_path = std::env::temp_dir().join(format!(
        "fullmag-quality-data-{}-{}.fmmq",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    let mut artifact = Vec::new();
    artifact.extend_from_slice(b"FMMQ");
    artifact.push(1);
    artifact.push(1);
    artifact.extend_from_slice(&0u16.to_le_bytes());
    artifact.extend_from_slice(&1u32.to_le_bytes());
    artifact.extend_from_slice(&0b111u32.to_le_bytes());
    artifact.extend_from_slice(&0u64.to_le_bytes());
    artifact.extend_from_slice(&0u64.to_le_bytes());
    artifact.extend_from_slice(&0.5f64.to_le_bytes());
    artifact.extend_from_slice(&0.25f64.to_le_bytes());
    artifact.extend_from_slice(&(1.0f64 / 6.0).to_le_bytes());
    fs::write(&artifact_path, &artifact).unwrap();

    let state = test_app_state_with_live_session().await;
    if let Some(snapshot) = state.current_live_state.write().await.as_mut() {
        snapshot.mesh_workspace = Some(serde_json::json!({
            "quality_data_artifact": {
                "kind": "fmmq.v1",
                "schema_version": 1,
                "path": artifact_path,
                "byte_size": artifact.len(),
                "element_count": 1,
                "metrics": ["sicn", "gamma", "volume"]
            }
        }));
        snapshot.mesh_revision = 42;
    }
    let app = build_v2_router().with_state(state);

    let response = app
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/meshing/meshes/shared-domain/quality/per-element")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(response.status(), StatusCode::OK);
    assert_eq!(
        response
            .headers()
            .get("content-type")
            .and_then(|value| value.to_str().ok()),
        Some("application/octet-stream"),
    );
    let body = body_bytes(response).await;
    assert_eq!(&body[..4], b"FMMQ");
    assert_eq!(body.len(), artifact.len());
    let _ = fs::remove_file(artifact_path);
}

#[tokio::test]
async fn mesh_periodic_pairs_returns_v1_diagnostics() {
    let state = test_app_state_with_live_session().await;
    if let Some(snapshot) = state.current_live_state.write().await.as_mut() {
        snapshot.fem_mesh = Some(sample_periodic_fem_mesh_payload());
        snapshot.mesh_revision = 41;
        let mut scene = sample_scene_document();
        scene.revision = 41;
        snapshot.scene_document = Some(scene);
        snapshot.mesh_workspace = Some(serde_json::json!({
            "last_build_summary": {"source_scene_revision": 41}
        }));
    }
    let app = build_v2_router().with_state(state);

    let response = app
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/meshing/mesh/periodic_pairs.v1")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(response.status(), StatusCode::OK);
    let json = body_json(response).await;
    assert_eq!(json["schema_version"], "periodic_pairs.v1");
    assert_eq!(json["revision"], 41);
    assert_eq!(json["pairs"][0]["pair_id"], "x_periodic");
    assert_eq!(json["pairs"][0]["source_marker"], "x_min");
    assert_eq!(json["pairs"][0]["destination_marker"], "x_max");
    assert_eq!(json["pairs"][0]["paired_node_count"], 3);
    assert_eq!(
        json["pairs"][0]["node_pairs"],
        serde_json::json!([[0, 1], [2, 3], [4, 5]])
    );
    assert_eq!(json["pairs"][0]["mixed_domain_node_pair_count"], 0);
    assert_eq!(json["pairs"][0]["unpaired_source_node_count"], 0);
    assert_eq!(json["pairs"][0]["unpaired_destination_node_count"], 0);
    assert_eq!(json["pairs"][0]["unpaired_source_face_count"], 0);
    assert_eq!(json["pairs"][0]["unpaired_destination_face_count"], 0);
    assert_eq!(
        json["pairs"][0]["domain_node_pair_counts"],
        serde_json::json!({"magnetic": 2, "airbox": 1})
    );
    assert_eq!(
        json["pairs"][0]["boundary_face_pairs"],
        serde_json::json!([{
            "face_a": 0,
            "face_b": 1,
            "vertex_pairs": [[0, 1], [2, 3], [4, 5]],
            "translation_m": [1.0e-6, 0.0, 0.0],
            "translation_residual_m": 0.0,
            "area_residual_m2": 0.0,
            "source_marker": 10,
            "destination_marker": 11,
            "normal_dot": -1.0,
            "orientation": "opposed_normals"
        }])
    );
    assert_eq!(json["pairs"][0]["max_residual_m"], 0.0);
    assert_eq!(json["pairs"][0]["rms_residual_m"], 0.0);
    assert_eq!(json["pairs"][0]["status"], "valid");
    assert_eq!(json["status"], "valid");
    assert!(json["topology_fingerprint"]
        .as_str()
        .is_some_and(|value| value.starts_with("sha256:")));
    assert!(json["certificate_fingerprint"]
        .as_str()
        .is_some_and(|value| value.starts_with("sha256:")));
    assert_eq!(json["certificate_revision"], 41);
    assert_eq!(json["source_scene_revision"], 41);
}

#[tokio::test]
async fn mesh_periodic_pairs_binary_returns_deterministic_v1_payload() {
    let state = test_app_state_with_live_session().await;
    if let Some(snapshot) = state.current_live_state.write().await.as_mut() {
        snapshot.fem_mesh = Some(sample_periodic_fem_mesh_payload());
        snapshot.mesh_revision = 41;
    }
    let app = build_v2_router().with_state(state.clone());

    let response = app
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/meshing/mesh/periodic_pairs.v1.bin")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(response.status(), StatusCode::OK);
    assert_eq!(
        response
            .headers()
            .get(header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok()),
        Some("application/vnd.fullmag.periodic-pairs.v1"),
    );
    assert_eq!(
        response
            .headers()
            .get("x-fullmag-periodic-pairs-format")
            .and_then(|value| value.to_str().ok()),
        Some("FMPP.v1"),
    );
    let etag = response
        .headers()
        .get(header::ETAG)
        .expect("binary periodic-pairs response should include ETag")
        .clone();
    let body = body_bytes(response).await;
    assert_eq!(&body[..4], b"FMPP");
    assert_eq!(body[4], 1);
    assert!(body.len() > 32, "payload should include node/face pairs");

    let app = build_v2_router().with_state(state.clone());
    let repeat = app
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/meshing/mesh/periodic_pairs.v1.bin")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(repeat.status(), StatusCode::OK);
    assert_eq!(body, body_bytes(repeat).await);

    let app = build_v2_router().with_state(state);
    let unchanged = app
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/meshing/mesh/periodic_pairs.v1.bin")
                .header(header::IF_NONE_MATCH, etag)
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(unchanged.status(), StatusCode::NOT_MODIFIED);
}

#[tokio::test]
async fn mesh_periodic_pairs_etag_changes_when_residual_changes() {
    let state = test_app_state_with_live_session().await;
    if let Some(snapshot) = state.current_live_state.write().await.as_mut() {
        snapshot.fem_mesh = Some(sample_periodic_fem_mesh_payload());
        snapshot.mesh_revision = 41;
    }
    let app = build_v2_router().with_state(state.clone());
    let first = app
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/meshing/mesh/periodic_pairs.v1")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(first.status(), StatusCode::OK);
    let first_etag = first
        .headers()
        .get("etag")
        .expect("periodic-pairs response should include etag")
        .clone();
    let _ = body_json(first).await;

    let app = build_v2_router().with_state(state.clone());
    let unchanged = app
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/meshing/mesh/periodic_pairs.v1")
                .header("if-none-match", &first_etag)
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(unchanged.status(), StatusCode::NOT_MODIFIED);

    if let Some(snapshot) = state.current_live_state.write().await.as_mut() {
        snapshot
            .fem_mesh
            .as_mut()
            .expect("periodic mesh should remain present")
            .nodes[1][0] += 1.0e-15;
    }
    let app = build_v2_router().with_state(state);
    let second = app
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/meshing/mesh/periodic_pairs.v1")
                .header("if-none-match", first_etag)
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(second.status(), StatusCode::OK);
}

