#[tokio::test]
async fn frequency_domain_manifest_reports_solver_family_availability() {
    let app = test_router();

    let response = app
        .oneshot(
            Request::builder()
                .uri("/v2/sessions/current/analysis/frequency-domain/manifest.v1")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(response.status(), StatusCode::OK);
    let json = body_json(response).await;
    assert_eq!(json["schema_version"], "frequency_domain_manifest.v1");
    assert_eq!(json["family_namespace"], "frequencyDomain");
    assert_eq!(json["eigen_namespace"], "eigen");
    assert_eq!(
        json["existing_frequency_response_namespace_preserved"],
        true
    );
    assert_eq!(json["response"]["study_kind"], "frequency_response");
    assert_eq!(json["eigenmodes"]["study_kind"], "eigenmodes");
    assert!(
        matches!(
            json["response"]["status"].as_str(),
            Some("ok" | "unavailable")
        ),
        "response availability status must come from the runner/native probe"
    );
    assert_eq!(
        json["response"]["driven_response_available"],
        serde_json::Value::Bool(json["response"]["status"] == "ok")
    );
    assert_eq!(json["response"]["modal_solver_available"], false);
    assert_eq!(
        json["response"]["static_periodic_response_available"],
        serde_json::Value::Bool(json["response"]["status"] == "ok")
    );
    assert_eq!(json["response"]["floquet_modal_available"], false);
    assert_eq!(json["response"]["floquet_response_available"], false);
    assert_eq!(json["response"]["dynamic_demag_k_available"], false);
    assert_eq!(json["response"]["gpu_available"], false);
    assert!(json["response"]["reason"].is_string());
    assert!(json["response"]["diagnostics_json"].is_string());
    assert_eq!(json["eigenmodes"]["modal_solver_available"], false);
    assert_eq!(json["eigenmodes"]["driven_response_available"], false);
    assert_eq!(
        json["eigenmodes"]["static_periodic_response_available"],
        false
    );
    assert_eq!(json["eigenmodes"]["floquet_modal_available"], false);
    assert_eq!(json["eigenmodes"]["floquet_response_available"], false);
    assert_eq!(json["eigenmodes"]["dynamic_demag_k_available"], false);
    assert_eq!(json["eigenmodes"]["gpu_available"], false);
    assert_eq!(json["floquet_nonzero_k_response_supported"], false);
    assert_eq!(json["floquet_nonzero_k_demag_supported"], false);
    assert_eq!(
        json["capabilities"]["schema_version"],
        "frequency_domain_capabilities.v1"
    );
    assert_eq!(
        json["capabilities"]["response"]["magnetic_cpu"]["status"],
        "partial_production_executable"
    );
    assert!(json["capabilities"]["response"]["magnetic_cpu"]["reason"]
        .as_str()
        .expect("magnetic_cpu reason should be a string")
        .contains("bulk-DMI"));
    assert!(
        matches!(
            json["capabilities"]["response"]["magnetic_gpu"]["status"].as_str(),
            Some("unsupported" | "partial_production_executable")
        ),
        "magnetic GPU capability must reflect the native frequency-domain availability probe"
    );
    assert_eq!(
        json["capabilities"]["demag"]["floquet_dynamic_k"]["status"],
        "unsupported"
    );
    assert_eq!(
        json["capabilities"]["dispersion"]["reference_cpu"]["status"],
        "reference_executable"
    );
    assert_eq!(
        json["capabilities"]["dispersion"]["production_cpu"]["status"],
        "partial_production_executable"
    );
    assert_eq!(
        json["capabilities"]["dispersion"]["production_cpu_gamma_k_path"]["status"],
        "partial_production_executable"
    );
    assert!(
        json["capabilities"]["dispersion"]["production_cpu_gamma_k_path"]["reason"]
            .as_str()
            .expect("production_cpu_gamma_k_path dispersion reason should be a string")
            .contains("gamma-equivalent")
    );
    assert!(
        json["capabilities"]["dispersion"]["production_cpu"]["reason"]
            .as_str()
            .expect("production_cpu dispersion reason should be a string")
            .contains("Bloch/Floquet tangent payload")
    );
    assert_eq!(
        json["capabilities"]["dispersion"]["production_gpu"]["status"],
        "unsupported"
    );
    assert!(
        json["capabilities"]["dispersion"]["production_gpu"]["reason"]
            .as_str()
            .expect("production_gpu dispersion reason should be a string")
            .contains("modal GPU")
    );
    assert_eq!(
        json["capabilities"]["visualization"]["mode_3d_overlay"]["status"],
        "reference_executable"
    );
    assert_eq!(json["response_progress"], serde_json::Value::Null);
}

