#[tokio::test]
async fn authoring_region_owned_resources_expose_authored_payloads() {
    let state = test_app_state_with_live_session().await;
    let mut scene = sample_scene_document();
    scene.revision = 31;
    let region: fullmag_authoring::SceneObjectRegion = serde_json::from_value(serde_json::json!({
        "region_id": "body:core",
        "owner_object": "body",
        "name": "core",
        "shape": { "kind": "cylinder", "radius": 3.0e-8, "height": 2.0e-9, "center": [0.0, 0.0, 0.0], "axis": [0.0, 0.0, 1.0] },
        "frame": "object",
        "enabled": true,
        "priority": 7,
        "magnetization_ref": "mag:core",
        "mesh_policy": { "maximum_element_size": 1.0e-9 },
        "material_overrides": [{
            "parameter": "Ms",
            "value": { "kind": "constant", "value": 760000.0, "unit": "A/m" },
            "priority": 7,
            "conflict_policy": "error"
        }],
        "texture_override": {
            "initial_magnetization": { "kind": "uniform", "value": [0.0, 0.0, 1.0] }
        },
        "realization_policy": "conformal"
    })).unwrap();
    scene.objects[0].regions.push(region);
    scene.objects[0].region_overrides.insert(
        "body:core".to_string(),
        fullmag_authoring::SceneRegionOverride {
            magnetization_ref: Some("mag:core".to_string()),
        },
    );
    let field: fullmag_authoring::SceneMaterialParameterAssignment =
        serde_json::from_value(serde_json::json!({
            "assignment_id": "body_core_ms_gradient",
            "owner_object": "body",
            "parameter": "Ms",
            "region_id": "body:core",
            "priority": 3,
            "conflict_policy": "error",
            "value": {
                "kind": "linear",
                "base": 760000.0,
                "gradient": [0.0, 1.0e11, 0.0],
                "unit": "A/m",
                "frame": "object"
            }
        }))
        .unwrap();
    scene.objects[0].material_parameter_fields.push(field);
    let coupling: fullmag_authoring::SceneCoupling = serde_json::from_value(serde_json::json!({
        "coupling_id": "body_top_reference_bottom_rkky",
        "kind": "rkky",
        "source": { "kind": "surface", "object": "body", "selector": "top" },
        "target": { "kind": "surface", "object": "reference", "selector": "bottom" },
        "enabled": true,
        "parameters": { "kind": "rkky", "J1": -0.0003 },
        "capability_policy": "require_runtime"
    }))
    .unwrap();
    scene.couplings.push(coupling);
    if let Some(snapshot) = state.current_live_state.write().await.as_mut() {
        snapshot.scene_document = Some(scene);
        snapshot.session.script_path.clear();
        snapshot.region_realization_revisions = fullmag_authoring::RegionRealizationRevisions {
            topology: 41,
            membership: 42,
            coefficients: 43,
            initial_state: 44,
        };
    }
    let app = build_v2_router().with_state(state.clone());

    let regions_response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/v2/sessions/current/model/regions")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let status = regions_response.status();
    let regions = body_json(regions_response).await;
    assert_eq!(status, StatusCode::OK, "{regions:#}");
    assert_eq!(regions["regions"].as_array().unwrap().len(), 1);
    assert!(regions["regions"]
        .as_array()
        .unwrap()
        .iter()
        .all(|region| region["source"] == "authored_object_region"));
    let authored_region = regions["regions"]
        .as_array()
        .unwrap()
        .iter()
        .find(|region| region["region_id"] == "body:core")
        .expect("authored region resource");
    assert_eq!(authored_region["source"], "authored_object_region");
    assert_eq!(authored_region["region_kind"], "object_region");
    assert_eq!(authored_region["owner_object_id"], "body");
    assert_eq!(authored_region["priority"], 7);
    assert_eq!(authored_region["frame"], "object");
    assert_eq!(authored_region["shape"]["kind"], "cylinder");
    assert_eq!(
        authored_region["mesh_policy"]["maximum_element_size"],
        1.0e-9
    );
    assert_eq!(authored_region["material_overrides"][0]["parameter"], "ms");
    assert_eq!(authored_region["magnetization_ref"], "mag:core");
    assert_eq!(
        authored_region["texture_override"]["initial_magnetization"]["kind"],
        "uniform"
    );
    assert_eq!(
        authored_region["material_parameter_fields"][0]["assignment_id"],
        "body_core_ms_gradient"
    );
    assert_eq!(
        authored_region["realization_status"],
        "authored_pending_realization"
    );
    assert_eq!(regions["region_topology_revision"], 41);
    assert_eq!(regions["region_membership_revision"], 42);
    assert_eq!(regions["region_coefficients_revision"], 43);
    assert_eq!(regions["region_initial_state_revision"], 44);

    let realized_regions_response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/v2/sessions/current/model/realized-regions")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let status = realized_regions_response.status();
    let realized_regions = body_json(realized_regions_response).await;
    assert_eq!(status, StatusCode::OK, "{realized_regions:#}");
    assert_eq!(realized_regions["scene_revision"], 31);
    assert_eq!(realized_regions["geometry_realization_revision"], 31);
    assert_eq!(realized_regions["regions"].as_array().unwrap().len(), 1);
    let realized_region = &realized_regions["regions"][0];
    assert_eq!(realized_region["source"], "realized_geometry_region");
    assert_eq!(realized_region["region_kind"], "realized_body_region");
    assert_eq!(realized_region["owner_object_id"], "body");
    assert_eq!(realized_region["region_id"], "region:body");
    assert_eq!(realized_region["source_object_ids"][0], "body");
    assert!(realized_region["source_body_ids"][0]
        .as_str()
        .unwrap()
        .starts_with("body:body:"));
    assert_eq!(realized_region["material_ref"], "mat:body");
    assert_eq!(realized_region["realization_status"], "realized");
    assert!(realized_region["shape"].is_null());
    assert!(realized_region["material_overrides"].is_null());

    let diagnostics_response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/v2/sessions/current/model/region-diagnostics")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let status = diagnostics_response.status();
    let diagnostics = body_json(diagnostics_response).await;
    assert_eq!(status, StatusCode::OK, "{diagnostics:#}");
    let diagnostic_codes = diagnostics["diagnostics"]
        .as_array()
        .unwrap()
        .iter()
        .map(|diagnostic| diagnostic["code"].as_str().unwrap())
        .collect::<BTreeSet<_>>();
    assert!(diagnostic_codes.contains("authored_region_pending_realization"));
    assert!(diagnostic_codes.contains("region_mesh_policy_requires_rebuild"));
    assert!(!diagnostic_codes.contains("region_material_realization_pending"));
    assert!(diagnostic_codes.contains("region_material_realization_required"));
    assert!(diagnostic_codes.contains("region_realization_policy_capability_gated"));
    assert!(diagnostics["diagnostics"]
        .as_array()
        .unwrap()
        .iter()
        .all(|diagnostic| diagnostic["region_id"] == "body:core"
            && diagnostic["owner_object_id"] == "body"));
    assert_eq!(diagnostics["region_topology_revision"], 41);
    assert_eq!(diagnostics["region_membership_revision"], 42);
    assert_eq!(diagnostics["region_coefficients_revision"], 43);
    assert_eq!(diagnostics["region_initial_state_revision"], 44);

    let fields_response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/v2/sessions/current/model/material-fields")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let status = fields_response.status();
    let fields = body_json(fields_response).await;
    assert_eq!(status, StatusCode::OK, "{fields:#}");
    assert_eq!(
        fields["fields"][0]["assignment_id"],
        "body_core_ms_gradient"
    );
    assert_eq!(fields["fields"][0]["owner_object_id"], "body");
    assert_eq!(fields["fields"][0]["source_region_id"], "body:core");
    assert_eq!(fields["fields"][0]["parameter"], "ms");
    assert_eq!(fields["fields"][0]["unit"], "A/m");
    assert_eq!(fields["fields"][0]["frame"], "object");
    assert_eq!(fields["region_coefficients_revision"], 43);

    let material_response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/v2/sessions/current/model/materials/mat:body")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let status = material_response.status();
    let material = body_json(material_response).await;
    assert_eq!(status, StatusCode::OK, "{material:#}");
    assert_eq!(material["region_coefficients_revision"], 43);

    let couplings_response = app
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/v2/sessions/current/model/couplings")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let status = couplings_response.status();
    let couplings = body_json(couplings_response).await;
    assert_eq!(status, StatusCode::OK, "{couplings:#}");
    assert_eq!(
        couplings["couplings"][0]["coupling_id"],
        "body_top_reference_bottom_rkky"
    );
    assert_eq!(couplings["couplings"][0]["coupling_kind"], "rkky");
    assert_eq!(couplings["couplings"][0]["source"]["selector"], "top");
    assert_eq!(couplings["couplings"][0]["params"]["j1"], -0.0003);
    assert_eq!(
        couplings["couplings"][0]["realization_status"],
        "requires_runtime_capability"
    );
    assert_eq!(
        couplings["couplings"][0]["source_resolution"]["status"],
        "pending_mesh_resolution"
    );
    assert_eq!(
        couplings["couplings"][0]["source_resolution"]["object_id"],
        "body"
    );
    assert_eq!(
        couplings["couplings"][0]["source_resolution"]["selector"],
        "top"
    );
    assert_eq!(
        couplings["couplings"][0]["target_resolution"]["status"],
        "pending_mesh_resolution"
    );
    assert!(couplings["couplings"][0]["blocker_reason"]
        .as_str()
        .is_some_and(|reason| reason.contains("RKKY runtime operator")));

    // REDO ETAP 4 Test: Add execution plan metadata and apply it to verify realized field status/statistics
    let plan_json = serde_json::json!({
        "common": {
            "ir_version": "1.0.0",
            "requested_backend": "fdm",
            "resolved_backend": "fdm",
            "execution_mode": "relaxation",
            "material_field_plans": []
        },
        "backend_plan": {
            "kind": "fdm",
            "grid": { "cells": [4, 1, 1] },
            "cell_size": [1e-9, 1e-9, 1e-9],
            "region_mask": [0, 0, 0, 0],
            "initial_magnetization": [],
            "material": {
                "name": "body",
                "saturation_magnetisation": 800000.0,
                "exchange_stiffness": 1.3e-11,
                "damping": 0.5,
                "ms_field": [760000.0, 770000.0, 780000.0, 790000.0],
                "a_field": [1.3e-11, 1.3e-11, 1.3e-11, 1.3e-11],
                "alpha_field": [0.5, 0.5, 0.5, 0.5]
            },
            "enable_exchange": true,
            "enable_demag": true,
            "gyromagnetic_ratio": 2.21e5,
            "precision": "double",
            "exchange_bc": "free",
            "integrator": "heun"
        },
        "output_plan": { "quantities": [] },
        "provenance": { "git_commit": "unknown" }
    });

    let metadata = serde_json::json!({
        "execution_plan": plan_json
    });

    if let Some(snapshot) = state.current_live_state.write().await.as_mut() {
        crate::session::apply_current_live_metadata(snapshot, metadata);
    }

    let fields_response_realized = build_v2_router()
        .with_state(state.clone())
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/v2/sessions/current/model/material-fields")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let status_realized = fields_response_realized.status();
    let fields_realized = body_json(fields_response_realized).await;
    assert_eq!(status_realized, StatusCode::OK, "{fields_realized:#}");

    // Find our assignment_id "body_core_ms_gradient"
    let field_list = fields_realized["fields"].as_array().unwrap();
    let ms_field_res = field_list
        .iter()
        .find(|f| f["assignment_id"] == "body_core_ms_gradient")
        .unwrap();

    assert_eq!(ms_field_res["realization_status"], "realized");
    assert_eq!(ms_field_res["sample_count"], 4);
    assert_eq!(ms_field_res["min"], 760000.0);
    assert_eq!(ms_field_res["max"], 790000.0);
    assert_eq!(ms_field_res["mean"], 775000.0);
}

