#[test]
fn openapi_contains_field_slice_contract() {
    let openapi = crate::openapi_v2::openapi_json();
    let value = openapi;
    let paths = value
        .get("paths")
        .and_then(|p| p.as_object())
        .expect("OpenAPI paths must be an object");
    let components = value
        .get("components")
        .and_then(|c| c.get("schemas"))
        .and_then(|s| s.as_object())
        .expect("OpenAPI schemas must be present");

    let vector_get = paths
        .get("/v2/sessions/current/data/fields/{quantity_id}/samples/vector")
        .and_then(|p| p.get("get"))
        .expect("vector GET path missing");
    let vector_params = vector_get
        .get("parameters")
        .and_then(|p| p.as_array())
        .expect("vector GET parameters missing");
    assert!(
        vector_params.iter().any(|p| {
            p.get("name").and_then(|n| n.as_str()) == Some("component")
                && p.get("in").and_then(|i| i.as_str()) == Some("query")
        }),
        "vector GET should expose query param `component`"
    );
    let response_headers = vector_get["responses"]["200"]["headers"]
        .as_object()
        .expect("vector 200 response headers missing");
    for header_name in [
        "x-fullmag-field-revision",
        "x-fullmag-domain-generation-id",
        "x-fullmag-quantity-id",
        "x-fullmag-component",
        "x-fullmag-encoding",
        "x-fullmag-point-count",
        "x-fullmag-value-count",
        "x-fullmag-n-comp",
        "x-fullmag-scope-kind",
        "x-fullmag-scope-id",
        "x-fullmag-snapshot-id",
        "x-fullmag-mesh-topology-hash",
        "x-fullmag-field-indexing",
        "x-fullmag-node-index-count",
    ] {
        assert!(
            response_headers.contains_key(header_name),
            "missing documented response header {header_name}"
        );
    }
    for parameter in ["expected_generation_id", "expected_carrier_revision"] {
        assert!(
            vector_params.iter().any(|entry| entry["name"] == parameter),
            "vector GET should expose query precondition {parameter}"
        );
    }
    assert_eq!(
        vector_get["responses"]["202"]["content"]["application/json"]["schema"]["$ref"],
        "#/components/schemas/FieldVectorPendingResponse"
    );
    let vector_responses = vector_get
        .get("responses")
        .and_then(|responses| responses.as_object())
        .expect("vector GET responses missing");
    assert!(vector_responses["202"]["description"]
        .as_str()
        .is_some_and(|description| {
            description.contains("reason_code") && description.contains("retry_after_ms")
        }));
    assert!(vector_responses["200"]["description"]
        .as_str()
        .is_some_and(|description| {
            description.contains("max_samples")
                && description.contains("FMVP v3 sampled indices")
                && description.contains("FMVP v2")
        }));
    assert!(vector_responses["204"]["description"]
        .as_str()
        .is_some_and(|description| {
            description.contains("no materialized source") && description.contains("pending")
        }));
    assert!(vector_responses["404"]["description"]
        .as_str()
        .is_some_and(|description| {
            description.contains("Unknown quantity or scope") && description.contains("invalid")
        }));
    assert!(vector_responses["409"]["description"]
        .as_str()
        .is_some_and(|description| {
            description.contains("Stale") && description.contains("carrier")
        }));
    for status in ["400", "404", "409"] {
        assert_eq!(
            vector_responses[status]["content"]["application/json"]["schema"]["$ref"],
            "#/components/schemas/ApiErrorResponse",
            "vector {status} response should expose the typed API error body"
        );
    }
    let max_samples = vector_params
        .iter()
        .find(|parameter| parameter["name"] == "max_samples")
        .expect("vector GET should expose max_samples");
    assert_eq!(max_samples["schema"]["minimum"], 1);
    assert!(max_samples["description"]
        .as_str()
        .is_some_and(|description| {
            description.contains("at most `K`")
                && description.contains("full-domain")
                && description.contains("FMVP v3")
        }));
    assert!(
        components.contains_key("FieldVectorPendingResponse"),
        "OpenAPI missing FieldVectorPendingResponse schema"
    );

    let slice_meta_get = paths
        .get("/v2/sessions/current/data/fields/{quantity_id}/samples/slice/meta")
        .and_then(|p| p.get("get"))
        .expect("slice/meta GET path missing");
    let slice_meta_params = slice_meta_get
        .get("parameters")
        .and_then(|p| p.as_array())
        .expect("slice/meta parameters missing");
    assert!(
        slice_meta_params
            .iter()
            .any(|p| p.get("name").and_then(|n| n.as_str()) == Some("plane")),
        "slice/meta should expose query param `plane`"
    );
    assert!(
        slice_meta_get
            .get("responses")
            .and_then(|r| r.get("409"))
            .is_some(),
        "slice/meta should document 409 response"
    );

    assert!(
        components.contains_key("FieldSliceMeta"),
        "OpenAPI missing FieldSliceMeta schema"
    );
    assert!(
        components.contains_key("FieldProjectionMeta"),
        "OpenAPI missing FieldProjectionMeta schema"
    );
    assert!(
        components.contains_key("FieldMatrixResponse"),
        "OpenAPI missing FieldMatrixResponse schema"
    );
    assert!(
        components.contains_key("FieldProjectionMaskDescriptor"),
        "OpenAPI missing FieldProjectionMaskDescriptor schema"
    );
    assert!(
        components.contains_key("FieldSliceGrid"),
        "OpenAPI missing FieldSliceGrid schema"
    );
    assert!(
        components.contains_key("FieldSliceBounds"),
        "OpenAPI missing FieldSliceBounds schema"
    );
    assert!(
        components.contains_key("FieldSliceBinaryDescriptor"),
        "OpenAPI missing FieldSliceBinaryDescriptor schema"
    );
    let field_vector_view_description = components
        .get("FieldVectorQuery")
        .and_then(|schema| schema.get("properties"))
        .and_then(|properties| properties.get("view"))
        .and_then(|view| view.get("description"))
        .and_then(|description| description.as_str())
        .expect("FieldVectorQuery.view should document supported analysis views");
    assert!(
        field_vector_view_description.contains("`complex`")
            && field_vector_view_description.contains("`abs`")
            && field_vector_view_description.contains("`phase_rotated_real`"),
        "FieldVectorQuery.view should document complex, abs, and phase-rotated frequency-domain views"
    );
}

