#[tokio::test]
async fn spin_transport_api_returns_opaque_variants_losslessly_as_read_only() {
    let state = test_app_state_with_live_session().await;
    let opaque = serde_json::json!({
        "id": "future-spin",
        "schema_version": "vendor.spin.v9",
        "nested": { "tensor": [[1, 2], [3, 4]] }
    });
    if let Some(snapshot) = state.current_live_state.write().await.as_mut() {
        let mut scene = sample_scene_document();
        scene.spin_transports =
            serde_json::from_value(serde_json::json!([opaque.clone()])).unwrap();
        snapshot.scene_document = Some(scene);
        snapshot.session.script_path.clear();
    }
    let app = build_v2_router().with_state(state.clone());
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method(Method::GET)
                .uri("/v2/sessions/current/model/spin-transports")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK);
    assert_eq!(body_json(response).await["items"][0], opaque);

    let before = state
        .current_live_state
        .read()
        .await
        .as_ref()
        .unwrap()
        .scene_document
        .clone()
        .unwrap();
    let response = app
        .oneshot(
            Request::builder()
                .method(Method::PATCH)
                .uri("/v2/sessions/current/model/spin-transports/future-spin")
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(
                    serde_json::json!({
                        "base_revision": before.revision,
                        "resource": opaque
                    })
                    .to_string(),
                ))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::BAD_REQUEST);
    let after = state
        .current_live_state
        .read()
        .await
        .as_ref()
        .unwrap()
        .scene_document
        .clone()
        .unwrap();
    assert_eq!(
        serde_json::to_value(after).unwrap(),
        serde_json::to_value(before).unwrap()
    );
}

